INSERT INTO serving.agg_kehadiran_departemen_harian(tanggal,departemen_key,active_employee_days,checkin_days,checkout_days,no_checkin_days,no_checkout_days,leave_days,required_checkin_days,required_checkout_days,excused_checkin_days,excused_checkout_days,required_checkin_present_days,required_checkout_present_days,fact_rows,review_rows,nonfinal_rows,serving_batch_id)
SELECT tanggal,departemen_key,SUM(active_employee_days),SUM(checkin_days),SUM(checkout_days),SUM(no_checkin_days),SUM(no_checkout_days),SUM(leave_days),SUM(required_checkin_days),SUM(required_checkout_days),SUM(excused_checkin_days),SUM(excused_checkout_days),SUM(required_checkin_present_days),SUM(required_checkout_present_days),count(*),count(*) FILTER(WHERE perlu_review),count(*) FILTER(WHERE NOT is_date_final),'TEST_SCHEMA' FROM mart_kehadiran.fact_kehadiran_daily GROUP BY tanggal,departemen_key;
SELECT pg_temp.assert_ok((SELECT (active_employee_days,checkin_days,checkout_days,no_checkin_days,no_checkout_days,leave_days,required_checkin_days,required_checkout_days,excused_checkin_days,excused_checkout_days,required_checkin_present_days,required_checkout_present_days)=(6,2,3,2,1,4,3,3,3,3,1,2) FROM serving.v_kehadiran_instansi_harian WHERE tanggal='2026-10-28'),'all 12 measures incl UNKNOWN and full leave event');
SELECT pg_temp.assert_ok((SELECT abs(checkin_rate-100.0*2/6)<0.00001 AND abs(required_checkout_rate-100.0*2/3)<0.00001 AND is_provisional AND NOT is_data_complete FROM serving.v_kehadiran_instansi_harian WHERE tanggal='2026-10-28'),'weighted ratios and missing date state');
SELECT pg_temp.assert_ok((SELECT checkin_rate IS NULL AND required_checkout_rate IS NULL AND fact_rows=1 AND active_employee_days=0 FROM serving.v_kehadiran_instansi_harian WHERE tanggal='2026-10-29'),'zero denominator and inactive event');
SELECT pg_temp.assert_ok((SELECT checkin_days=1 AND checkin_event_count=2 FROM mart_kehadiran.fact_kehadiran_daily WHERE pegawai_id_sumber=1),'two shifts one employee');
INSERT INTO serving.attendance_date_state VALUES ('2026-10-28',true,true,true,'TEST_SCHEMA',current_timestamp);
SELECT pg_temp.assert_ok((SELECT is_provisional AND is_data_complete FROM serving.v_kehadiran_instansi_harian WHERE tanggal='2026-10-28'),'complete state cannot finalize provisional facts');
